import 'dart:math' as math;

import 'cdc_stature_lms.dart';

/// Height for age against the US CDC 2000 growth charts (stature-for-age,
/// 2 to 20 years), the single reference every percentile in the app uses.
///
/// The table holds the CDC LMS parameters (lib/utils/cdc_stature_lms.dart,
/// generated by tool/gen_cdc_reference.py from the official statage.csv).
/// For a height X at an age with parameters L, M, S:
///   z = ((X / M)^L - 1) / (L * S)      (L != 0)
///   z = ln(X / M) / S                  (L == 0)
///   percentile = Phi(z)
/// Ages are in months and interpolated linearly between table rows. Below
/// 24 months the 24 month row is used, above 20 years the 240 month row
/// (adult height), since the charts stop there.
///
/// There is no ethnicity adjustment: CDC is a population reference for the
/// whole US population, not a per-group standard. The old offsets were deltas
/// against a global (NCD-RisC) mean and do not apply on top of it.
class HeightReference {
  HeightReference._();

  static const double minMonths = 24;
  static const double maxMonths = 240;

  // ── Age helpers ──────────────────────────────────────────────────

  /// Age in months for a whole age in years: the middle of that year, which
  /// is how a "15 year old" spreads over 180 to 192 months.
  static double monthsForAge(int age) => age * 12.0 + 6.0;

  /// Exact age in months from an ISO birth date (`yyyy-MM-dd`).
  static double ageMonthsFromBirthDate(String birthDate, {DateTime? now}) {
    final birth = DateTime.tryParse(birthDate);
    if (birth == null) return maxMonths;
    final today = now ?? DateTime.now();
    final days = today.difference(birth).inHours / 24.0;
    return days / 30.4375;
  }

  // ── LMS lookup ───────────────────────────────────────────────────

  /// L, M, S at [ageMonths], linear in months between the CDC rows.
  static ({double l, double m, double s}) lms(double ageMonths, bool isMale) {
    final rows = isMale ? cdcStatureLmsMale : cdcStatureLmsFemale;
    final a = ageMonths.clamp(minMonths, maxMonths).toDouble();
    if (a <= rows.first[0]) {
      return (l: rows.first[1], m: rows.first[2], s: rows.first[3]);
    }
    for (var i = 1; i < rows.length; i++) {
      final hi = rows[i];
      if (a <= hi[0]) {
        final lo = rows[i - 1];
        final t = (a - lo[0]) / (hi[0] - lo[0]);
        double mix(int k) => lo[k] + (hi[k] - lo[k]) * t;
        return (l: mix(1), m: mix(2), s: mix(3));
      }
    }
    final last = rows.last;
    return (l: last[1], m: last[2], s: last[3]);
  }

  /// CDC z-score of [heightCm] at [ageMonths].
  static double zScore(double heightCm, double ageMonths, bool isMale) {
    final p = lms(ageMonths, isMale);
    if (heightCm <= 0) return -10;
    if (p.l.abs() < 1e-9) return math.log(heightCm / p.m) / p.s;
    return (math.pow(heightCm / p.m, p.l) - 1) / (p.l * p.s);
  }

  /// Height (cm) at z-score [z] at [ageMonths].
  static double heightAtZ(double z, double ageMonths, bool isMale) {
    final p = lms(ageMonths, isMale);
    if (p.l.abs() < 1e-9) return p.m * math.exp(p.s * z);
    final base = 1 + p.l * p.s * z;
    if (base <= 0) return 0;
    return p.m * math.pow(base, 1 / p.l).toDouble();
  }

  /// Height (cm) at percentile [pct] (0 to 100, exclusive).
  static double heightAtPercentile(double pct, double ageMonths, bool isMale) =>
      heightAtZ(_normInv((pct / 100).clamp(1e-6, 1 - 1e-6)), ageMonths, isMale);

  // ── Public API (age in years, exact months when known) ───────────

  /// Median height (cm) at [age], or at [ageMonths] when given.
  static double getMean(int age, bool isMale, {double? ageMonths}) =>
      lms(ageMonths ?? monthsForAge(age), isMale).m;

  /// Spread (cm) for drawing a bell curve: half the distance between the
  /// z = -1 and z = +1 heights, which for stature is close to M * S.
  static double getSd(int age, bool isMale, {double? ageMonths}) {
    final months = ageMonths ?? monthsForAge(age);
    return (heightAtZ(1, months, isMale) - heightAtZ(-1, months, isMale)) / 2;
  }

  /// Height percentile (0.1 to 99.9) for [heightCm] at [age], or at
  /// [ageMonths] when given.
  static double percentile({
    required double heightCm,
    required int age,
    required bool isMale,
    double? ageMonths,
  }) {
    final z = zScore(heightCm, ageMonths ?? monthsForAge(age), isMale);
    return (_normCdf(z) * 100).clamp(0.1, 99.9);
  }

  /// Heights at the 5th, 25th, 50th, 75th and 95th percentile.
  /// Keys: 'p5', 'p25', 'p50', 'p75', 'p95'
  static Map<String, double> referenceHeights(
    int age,
    bool isMale, {
    double? ageMonths,
  }) {
    final months = ageMonths ?? monthsForAge(age);
    return {
      'p5': heightAtZ(-1.6449, months, isMale),
      'p25': heightAtZ(-0.6745, months, isMale),
      'p50': heightAtZ(0, months, isMale),
      'p75': heightAtZ(0.6745, months, isMale),
      'p95': heightAtZ(1.6449, months, isMale),
    };
  }

  // ── Internal math ────────────────────────────────────────────────

  static double _normCdf(double z) =>
      0.5 * (1.0 + _erf(z / math.sqrt(2.0)));

  /// Error function, Abramowitz & Stegun 7.1.26 (max error < 1.5e-7).
  static double _erf(double x) {
    const p = 0.3275911;
    final sign = x < 0 ? -1.0 : 1.0;
    final t = 1.0 / (1.0 + p * x.abs());
    final y = 1.0 -
        (((((1.061405429 * t - 1.453152027) * t + 1.421413741) * t -
                    0.284496736) *
                t +
            0.254829592) *
            t *
            math.exp(-(x * x)));
    return sign * y;
  }

  /// Inverse standard normal CDF (Acklam, relative error < 1.2e-9).
  static double _normInv(double p) {
    const a = [
      -3.969683028665376e+01, 2.209460984245205e+02, -2.759285104469687e+02,
      1.383577518672690e+02, -3.066479806614716e+01, 2.506628277459239e+00,
    ];
    const b = [
      -5.447609879822406e+01, 1.615858368580409e+02, -1.556989798598866e+02,
      6.680131188771972e+01, -1.328068155288572e+01,
    ];
    const c = [
      -7.784894002430293e-03, -3.223964580411365e-01, -2.400758277161838e+00,
      -2.549732539343734e+00, 4.374664141464968e+00, 2.938163982698783e+00,
    ];
    const d = [
      7.784695709041462e-03, 3.224671290700398e-01, 2.445134137142996e+00,
      3.754408661907416e+00,
    ];
    const pLow = 0.02425;
    if (p < pLow) {
      final q = math.sqrt(-2 * math.log(p));
      return (((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q +
              c[5]) /
          ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1);
    }
    if (p > 1 - pLow) {
      final q = math.sqrt(-2 * math.log(1 - p));
      return -(((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q +
              c[5]) /
          ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1);
    }
    final q = p - 0.5;
    final r = q * q;
    return (((((a[0] * r + a[1]) * r + a[2]) * r + a[3]) * r + a[4]) * r +
            a[5]) *
        q /
        (((((b[0] * r + b[1]) * r + b[2]) * r + b[3]) * r + b[4]) * r + 1);
  }
}
